@startuml

class Library {
}

class RegisteredUser {
  +security_deposit : double
  +phone : string
  +email : string
  +mail : string
}

class BorrowableItem {
  +library_code : string
  +location : string
}

class Book {
  +publisher : string
  +authors : string[]
}

class MagazineIssue {
  +publication_date : date
  +publisher : string
}

class MusicCD {
  +publisher : string
  +artist : string
}

class VHSFilm {
  +duration : int
  +actors : string[]
  +publisher : string
}

class DVDFilm {
  +duration : int
  +actors : string[]
  +publisher : string
}

class Request {
}

Library "1" -- "*" RegisteredUser : has
Library "1" -- "*" BorrowableItem : has
RegisteredUser "0..1" -- "0..3" BorrowableItem : borrows
RegisteredUser "0..*" -- "0..*" Library : sends request to

BorrowableItem <|-- Book
BorrowableItem <|-- MagazineIssue
BorrowableItem <|-- MusicCD
BorrowableItem <|-- VHSFilm
BorrowableItem <|-- DVDFilm

@enduml

